// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import * as cola from "webcola";

import {
  measureLayoutConflicts,
  refineLayoutGeometry,
  separateHubBranches,
} from "../../../main/frontend/graph-explorer/graph-layout.ts";

function node(entityId, x, y, renderWidth = 124, renderHeight = 46) {
  return {
    entityId,
    x,
    y,
    renderWidth,
    renderHeight,
    width: renderWidth + 44,
    height: renderHeight + 32,
  };
}

test("mixed hub branches receive separate sectors and clear edge corridors", () => {
  const nodes = [node("root", 0, 0, 138)];
  const edges = [];

  for (let index = 0; index < 18; index += 1) {
    const angle = index * Math.PI * 2 / 18;
    const radius = 580 + (index % 3) * 42;
    nodes.push(
      node(
        `leaf-${index}`,
        Math.cos(angle) * radius,
        Math.sin(angle) * radius,
        index % 4 === 0 ? 210 : 118,
      ),
    );
    edges.push([0, nodes.length - 1]);
  }

  const familyStart = nodes.length;
  [
    [170, -105],
    [205, -30],
    [250, 50],
    [320, 108],
    [390, 42],
    [360, -68],
    [285, -130],
  ].forEach(([x, y], index) => {
    nodes.push(node(`family-${index}`, x, y, index === 3 ? 218 : 152));
  });
  edges.push(
    [0, familyStart],
    [0, familyStart + 1],
    [familyStart, familyStart + 1],
    [familyStart + 1, familyStart + 2],
    [familyStart + 2, familyStart + 3],
    [familyStart + 3, familyStart + 4],
    [familyStart + 4, familyStart + 5],
    [familyStart + 5, familyStart + 6],
    [familyStart + 6, familyStart],
  );

  const webColaLinks = edges.map(([source, target]) => ({
    source,
    target,
    length: 230,
  }));
  new cola.Layout()
    .size([1280, 780])
    .nodes(nodes)
    .links(webColaLinks)
    .avoidOverlaps(true)
    .linkDistance((edge) => edge.length)
    .convergenceThreshold(1e-4)
    .start(220, 0, 320, 0, false, true);

  const before = measureLayoutConflicts(nodes, edges);
  assert.ok(
    before.edgeNodeOverlaps > 0 || before.edgeCrossings > 0,
    "the seed should reproduce the obstructed automatic-layout geometry",
  );

  assert.equal(separateHubBranches(nodes, edges), true);
  const after = refineLayoutGeometry(nodes, edges, { passes: 8 });

  assert.equal(after.nodeOverlaps, 0);
  assert.equal(after.edgeNodeOverlaps, 0);
  assert.ok(after.edgeCrossings <= before.edgeCrossings);
  assert.ok(after.fanOverlaps <= before.fanOverlaps);
  assert.ok(nodes.every(({ x, y }) => Number.isFinite(x) && Number.isFinite(y)));
});

test("refinement moves an unrelated node out of an edge corridor", () => {
  const nodes = [
    node("source", -240, 0),
    node("target", 240, 0),
    node("obstacle", 0, 0, 176),
  ];
  const edges = [[0, 1]];

  assert.equal(measureLayoutConflicts(nodes, edges).edgeNodeOverlaps, 1);
  const after = refineLayoutGeometry(nodes, edges, { passes: 5 });
  assert.equal(after.nodeOverlaps, 0);
  assert.equal(after.edgeNodeOverlaps, 0);
});

test("refinement can uncross two independent edges by moving their endpoints", () => {
  const nodes = [
    node("north-west", -220, -170),
    node("south-east", 220, 170),
    node("south-west", -220, 170),
    node("north-east", 220, -170),
  ];
  const edges = [
    [0, 1],
    [2, 3],
  ];

  assert.equal(measureLayoutConflicts(nodes, edges).edgeCrossings, 1);
  const after = refineLayoutGeometry(nodes, edges, { passes: 7 });
  assert.equal(after.edgeCrossings, 0);
  assert.equal(after.nodeOverlaps, 0);
});

test("refinement still clears an edge corridor in a medium-size graph", () => {
  const nodes = [
    node("source", -240, 0),
    node("target", 240, 0),
    node("obstacle", 0, 0, 176),
  ];
  for (let index = 3; index < 120; index += 1) {
    nodes.push(node(`isolated-${index}`, 1_000 + index * 300, 1_000));
  }
  const edges = [[0, 1]];

  assert.equal(measureLayoutConflicts(nodes, edges).edgeNodeOverlaps, 1);
  const before = { x: nodes[2].x, y: nodes[2].y };
  const after = refineLayoutGeometry(nodes, edges, { passes: 5 });

  assert.equal(after.edgeNodeOverlaps, 0);
  assert.notDeepEqual({ x: nodes[2].x, y: nodes[2].y }, before);
});
